-- Source Product field contracts, no client/customer seed.
ALTER TABLE sys_role DROP INDEX sys_role_scope_key, ADD scope_key VARCHAR(80) GENERATED ALWAYS AS (IF(kind='PLATFORM','PLATFORM',CONCAT('FACTORY:',factory_id))) STORED, ADD UNIQUE KEY sys_role_scope_key(scope_key,role_key);
CREATE TABLE sys_message(message_id BIGINT PRIMARY KEY AUTO_INCREMENT,message_type VARCHAR(64),message_level VARCHAR(64),message_title VARCHAR(100) NOT NULL,message_content TEXT NOT NULL,sender_id BIGINT,sender_name VARCHAR(64),sender_nick VARCHAR(100),recipient_id BIGINT NOT NULL,recipient_name VARCHAR(64),recipient_nick VARCHAR(100),process_time DATETIME,call_back VARCHAR(255),status VARCHAR(16) NOT NULL DEFAULT 'UNREAD',deleted_flag CHAR(1) NOT NULL DEFAULT 'N',remark VARCHAR(500),attr1 VARCHAR(255),attr2 VARCHAR(255),attr3 BIGINT,attr4 BIGINT,create_by VARCHAR(64),create_time DATETIME,update_by VARCHAR(64),update_time DATETIME,KEY message_recipient(recipient_id,status),FOREIGN KEY(recipient_id) REFERENCES sys_user(user_id));
CREATE TABLE sys_attachment(attachment_id BIGINT PRIMARY KEY AUTO_INCREMENT,source_doc_id BIGINT,source_doc_type VARCHAR(64),file_url VARCHAR(500),base_path VARCHAR(255),file_name VARCHAR(160),orignal_name VARCHAR(160),file_type VARCHAR(100),file_size DECIMAL(20,0),remark VARCHAR(500),attr1 VARCHAR(255),attr2 VARCHAR(255),attr3 BIGINT,attr4 BIGINT,create_by VARCHAR(64),create_time DATETIME,update_by VARCHAR(64),update_time DATETIME,file_id VARCHAR(36) NOT NULL UNIQUE,owner_id BIGINT NOT NULL,factory_id VARCHAR(64),resource VARCHAR(128) NOT NULL,KEY attachment_owner_scope(owner_id,factory_id,resource),FOREIGN KEY(owner_id) REFERENCES sys_user(user_id));
INSERT INTO sys_attachment(file_id,owner_id,factory_id,resource,source_doc_type,file_url,file_name,orignal_name,file_type,file_size,create_time) SELECT id,owner_id,factory_id,resource,resource,CONCAT('/api/platform/files/',id,'/content?resource=',resource),original_name,original_name,'application/octet-stream',size,created_at FROM sys_file;
ALTER TABLE sys_file RENAME TO phase1_archived_private_file;
-- Persisted legacy sessions retained read-only; active sessions are identity-only Redis records.
ALTER TABLE sys_session RENAME TO phase1_archived_sys_session;
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,menu_type,visible,status,perms,create_time) SELECT '消息管理',menu_id,10,'message','system/message/index','C','0','0','system:message:list',CURRENT_TIMESTAMP FROM sys_menu WHERE path='system' AND menu_type='M' LIMIT 1;
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,menu_type,visible,status,perms,create_time) SELECT CONCAT('消息',x.a),m.menu_id,x.n,'','F','0','0',CONCAT('system:message:',x.a),CURRENT_TIMESTAMP FROM sys_menu m JOIN (SELECT 'query' a,1 n UNION ALL SELECT 'add',2 UNION ALL SELECT 'edit',3 UNION ALL SELECT 'remove',4 UNION ALL SELECT 'export',5) x WHERE m.perms='system:message:list' AND m.menu_type='C';
INSERT IGNORE INTO sys_role_menu SELECT DISTINCT r.role_id,m.menu_id FROM sys_role r JOIN sys_role_menu old ON old.role_id=r.role_id JOIN sys_menu granted ON granted.menu_id=old.menu_id AND granted.perms='system:role:add' CROSS JOIN sys_menu m WHERE r.kind='PLATFORM' AND m.perms LIKE 'system:message:%';
INSERT INTO sys_dict_type(dict_name,dict_type,status,create_time) VALUES('消息类型','sys_message_type','0',CURRENT_TIMESTAMP),('消息级别','sys_message_level','0',CURRENT_TIMESTAMP),('消息状态','sys_message_status','0',CURRENT_TIMESTAMP);
INSERT INTO sys_dict_data(dict_label,dict_value,dict_type,dict_sort,status) VALUES('通知','NOTICE','sys_message_type',1,'0'),('普通','INFO','sys_message_level',1,'0'),('紧急','WARN','sys_message_level',2,'0'),('未读','UNREAD','sys_message_status',1,'0'),('已读','READ','sys_message_status',2,'0'),('已处理','PROCEED','sys_message_status',3,'0');
